import React, { useState, useEffect, useCallback } from 'react';
import { Link, navigate } from 'gatsby';
import './Logout.css';
import { signOut } from '../../../hooks/useAuthService';
import { useGlobal } from '../../context/GlobalContext';

function Logout() {
  const [logoutState, setLogoutState] = useState({
    isLoggingOut: false,
    isLoggedOut: false,
    error: null
  });
  const { dispatch } = useGlobal();

  const performLogout = useCallback(async () => {
    try {
      await signOut();
      dispatch({ type: "LOGOUT" });
      setLogoutState(prev => ({
        ...prev,
        isLoggedOut: true,
        isLoggingOut: false
      }));
      navigate('/');
    } catch (error) {
      console.error("Logout error:", error);
      setLogoutState(prev => ({
        ...prev,
        error: error.message || "An error occurred during logout.",
        isLoggingOut: false
      }));
    }
  }, [dispatch]);

  const handleLogout = useCallback(() => {
    if (logoutState.isLoggingOut || logoutState.isLoggedOut) return;
    
    setLogoutState(prev => ({ ...prev, isLoggingOut: true, error: null }));
    
    // Add slight delay for better UX (shows loading state)
    const timer = setTimeout(() => {
      performLogout();
    }, 1500);

    return () => clearTimeout(timer);
  }, [logoutState.isLoggingOut, logoutState.isLoggedOut, performLogout]);

  useEffect(() => {
    // Auto-initiate logout after component mounts
    const autoLogoutTimer = setTimeout(() => {
      if (!logoutState.isLoggedOut && !logoutState.isLoggingOut) {
        handleLogout();
      }
    }, 1000);

    return () => clearTimeout(autoLogoutTimer);
  }, [logoutState.isLoggedOut, logoutState.isLoggingOut, handleLogout]);

  const handleCancel = useCallback((e) => {
    e.preventDefault();
    navigate(-1); // Go back to previous page
  }, []);

  return (
    <div className="logout-container-main">
      <div className="logout-card logout-container">
        <div className="logout-content">
          {logoutState.error ? (
            <div className="error-message">
              <div className="error-icon">
                <div className="icon-wrapper error">!</div>
              </div>
              <h2 className="error-title">Logout Failed</h2>
              <p className="error-subtitle">{logoutState.error}</p>
              <div className="logout-actions">
                <button onClick={handleLogout} className="retry-button">
                  Try Again
                </button>
                <button onClick={handleCancel} className="cancel-button">
                  Cancel
                </button>
              </div>
            </div>
          ) : !logoutState.isLoggedOut ? (
            <>
              <div className="logout-icon">
                <div className="icon-wrapper">
                  {logoutState.isLoggingOut ? (
                    <div className="logout-spinner"></div>
                  ) : (
                    '👋'
                  )}
                </div>
              </div>
              
              <h2 className="logout-title">
                {logoutState.isLoggingOut ? 'Securing Your Session...' : 'Goodbye!'}
              </h2>
              <p className="logout-subtitle">
                {logoutState.isLoggingOut 
                  ? 'We\'re securely ending your session and clearing all data.'
                  : 'You are about to be logged out of your account.'
                }
              </p>

              {!logoutState.isLoggingOut && (
                <div className="logout-actions">
                  <button 
                    onClick={handleLogout} 
                    className="confirm-logout-button"
                    disabled={logoutState.isLoggingOut}
                  >
                    Confirm Logout
                  </button>
                  <button 
                    onClick={handleCancel} 
                    className="cancel-button"
                  >
                    Stay Logged In
                  </button>
                </div>
              )}
            </>
          ) : (
            <div className="success-message">
              <div className="success-icon">
                <div className="icon-wrapper success">✓</div>
              </div>
              
              <h2 className="success-title">Successfully Logged Out</h2>
              <p className="success-subtitle">
                Thank you for using our service. Your session has been securely ended.
              </p>
              
              
            </div>
          )}
        </div>

        {/* Background Animation */}
        <div className="background-animation">
          <div className="floating-circle circle-1"></div>
          <div className="floating-circle circle-2"></div>
          <div className="floating-circle circle-3"></div>
        </div>
      </div>
    </div>
  );
};

export default Logout;